GLOSSARY = [
 ('RSC', 'Resource-Specific Consent: lets a Teams app read a team\'s channel messages without tenant-wide admin consent.'),
 ('Single-tenant bot', 'A bot registered in one Microsoft 365 organisation only; other organisations cannot add it.'),
 ('Raw-first', 'Store the raw input before parsing it, so parser bugs never lose data and can be reprocessed.'),
 ('Idempotency', 'Doing an operation twice has the same effect as once. Achieved with keys and unique constraints.'),
 ('Soft delete', 'Marking a row deleted (a timestamp) instead of removing it.'),
 ('Graph delta', 'A Microsoft Graph feature that returns only what changed since a cursor.'),
 ('Run-all', 'The backend job that runs every pipeline step in order; triggered every 15 minutes.'),
 ('Lease lock', 'A database row used as a mutex so two runs do not overlap; works through a transaction pooler.'),
 ('Transaction pooler', 'Supabase\'s pooler on port 6543: connections are shared per transaction, so prepared statements cannot be cached.'),
 ('RLS', 'Row Level Security: Postgres enforces row access rules; with no policies, only the owner role gets in.'),
 ('Data API', 'Supabase\'s auto-generated REST API over tables; turned off here.'),
 ('JWT', 'JSON Web Token: a signed token carrying claims (user id, expiry). Supabase issues one after sign-in.'),
 ('JWKS', 'A set of public keys published by the issuer; the backend verifies JWT signatures against it.'),
 ('ID token', 'A token from Google proving who signed in; exchanged with Supabase for a session.'),
 ('SHA-1 fingerprint', 'The hash of the app\'s signing certificate; Google OAuth needs it on the Android client or sign-in fails.'),
 ('FCM', 'Firebase Cloud Messaging: Google\'s push transport for Android.'),
 ('Expo Push Service', 'Expo\'s service that accepts push messages in batches and forwards them to FCM; returns tickets and receipts.'),
 ('Ticket / receipt', 'Expo returns a ticket when it accepts a push, and a receipt later saying whether it was delivered.'),
 ('Outbox (backend)', 'A table of alerts to send: write first, send later, mark the result.'),
 ('Outbox (app)', 'A persisted queue of the student\'s changes waiting to reach the server.'),
 ('Optimistic update', 'Change the screen immediately and reconcile with the server afterwards.'),
 ('Keyset pagination', 'Paging by "rows after this sort key" instead of OFFSET.'),
 ('Embedding', 'A vector (here 768 numbers) representing a text\'s meaning; similar texts have similar vectors.'),
 ('pgvector', 'A Postgres extension for storing vectors and searching by cosine similarity.'),
 ('Cosine similarity', 'A measure of how aligned two vectors are; used to rank passages for a question.'),
 ('Top-K retrieval', 'Taking the K most similar passages (here 8) as context.'),
 ('Redaction', 'Replacing emails, phones, ids and names with placeholders before text leaves the process.'),
 ('Prompt injection', 'Text inside the data that tries to give the model instructions; defended by treating context as data and validating outputs.'),
 ('Confidence / needs_review', 'Flags on events the AI is unsure about; shown as "unconfirmed" and excluded from automatic alerts and reminders.'),
 ('Event change', 'A recorded change (rescheduled, cancelled, venue changed...) with old and new values.'),
 ('Folding', 'Showing older cards inside the newest change card for the same event.'),
 ('Tombstone', 'A row marked deleted that remembers an item was switched off, so it does not come back.'),
 ('Virtual reminder', 'An automatic reminder computed on the fly with no stored row until the user edits or deletes it.'),
 ('Quiet hours', 'A window (default 23:00 to 07:00) during which pushes wait until it ends.'),
 ('Reanimated worklet', 'A function compiled to run on the UI thread so animations do not wait for the JS thread.'),
 ('Shared value', 'A Reanimated value readable on the UI thread without React re-rendering.'),
 ('TanStack Query', 'A data-fetching and cache library; here with a persisted cache for offline use.'),
 ('expo-router', 'File-based routing for Expo apps.'),
 ('EAS Build', 'Expo\'s cloud build service; produces the APK.'),
 ('EAS Update / OTA', 'Over-the-air JS updates delivered to installed apps without a store release.'),
 ('Channel', 'A named stream of updates (preview, production) an app build is attached to.'),
 ('Runtime version', 'A label (here the app version) an update must match to be applied to a build.'),
 ('Native fingerprint', 'A hash of everything native in the project; equal hashes prove an update needs no new build.'),
 ('Hermes', 'The JavaScript engine used by React Native here.'),
 ('WCAG AA', 'The accessibility contrast standard: 4.5:1 for body text, 3:1 for large text and icons.'),
 ('Reduced motion', 'The OS setting that asks apps to avoid movement; honoured by swapping movement for fades.'),
 ('SDD', 'Spec-driven development: specs first, implementation by task, decisions and deviations logged.'),
 ('DIFF', 'A logged deviation from a spec or a mismatch between spec and reality, with a status.'),
 ('Gate', 'A point where the assistant stops until the human tests, approves or acts.'),
 ('Mutation check', 'Put the bug back temporarily and confirm a test fails, to prove the test is real.'),
 ('Kill switch', 'A flag (AI_ENABLED, PUSH_ENABLED, CHAT_ENABLED) that turns a feature off without a deploy of code.'),
]

